import{_ as a,o as t,c as e,a2 as i}from"./chunks/framework.BWuWLRhz.js";const k=JSON.parse('{"title":"命令列搜尋（lff）","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/cli.md","filePath":"zh-HK/user-guide/cli.md","lastUpdated":1787586465000}'),l={name:"zh-HK/user-guide/cli.md"};function n(d,s,h,o,r,p){return t(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="命令列搜尋-lff" tabindex="-1">命令列搜尋（lff） <a class="header-anchor" href="#命令列搜尋-lff" aria-label="Permalink to &quot;命令列搜尋（lff）&quot;">​</a></h1><p>Lertaro 附帶了一個輕量高效的命令列伴侶工具 <strong><code>lff</code></strong>（Lertaro Fuzzy Finder）——一個專為終端機與腳本開發者打造的互動式模糊尋找工具。它直接透過本機具名管道與 Lertaro App 程序通訊，直接復用後台已構建的極速記憶體索引，無需在終端機中重新掃描磁碟。</p><h2 id="_1-為什麼選擇-lff" tabindex="-1">1. 為什麼選擇 lff <a class="header-anchor" href="#_1-為什麼選擇-lff" aria-label="Permalink to &quot;1. 為什麼選擇 lff&quot;">​</a></h2><ul><li><strong>共享索引，零 I/O 延遲</strong>：與 <code>fzf</code> 或 <code>find</code> 等傳統工具每次從頭巡覽磁碟不同，<code>lff</code> 毫秒級直接查詢 Lertaro 維護的千萬級檔案索引樹。</li><li><strong>一致的強大搜尋語法</strong>：完全繼承 Lertaro 的模糊跳躍比對、中文拼音別名比對與修飾符語法（詳見<a href="./search-syntax.html"><strong>搜尋語法</strong></a>）。</li><li><strong>快速失敗機制</strong>：<code>lff</code> 會自動偵測 Lertaro App 的運行狀態。若主程式未啟動，會立即向 <code>stderr</code> 列印友好的錯誤提示並退出，絕不阻塞終端機會話。</li></ul><h2 id="_2-安裝與-path-設定" tabindex="-1">2. 安裝與 PATH 設定 <a class="header-anchor" href="#_2-安裝與-path-設定" aria-label="Permalink to &quot;2. 安裝與 PATH 設定&quot;">​</a></h2><p><code>lff.exe</code> 隨 Lertaro 主程式一同打包分發：</p><ul><li><strong>安裝版</strong>：在安裝精靈的工作選取介面中勾選<strong>將 lff 命令列搜尋工具新增到 PATH</strong>，即可在任意終端機視窗中直接輸入 <code>lff</code> 運行。</li><li><strong>便攜版</strong>：將解壓目錄手動新增至系統的用戶或系統 <code>PATH</code> 環境變數中。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>修改 PATH 後，請新開啟一個終端機視窗以使環境變數生效；當前已開啟的終端機無法感知外部環境變數的變更。</p></div><h2 id="_3-互動介面與操作按鍵" tabindex="-1">3. 互動介面與操作按鍵 <a class="header-anchor" href="#_3-互動介面與操作按鍵" aria-label="Permalink to &quot;3. 互動介面與操作按鍵&quot;">​</a></h2><p>在終端機中輸入 <code>lff</code> 並按 Enter，即可進入全螢幕互動式搜尋介面：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span></span></code></pre></div><h3 id="常用互動快捷鍵" tabindex="-1">常用互動快捷鍵 <a class="header-anchor" href="#常用互動快捷鍵" aria-label="Permalink to &quot;常用互動快捷鍵&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">按鍵</th><th style="text-align:left;">功能說明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>直接輸入字元</strong></td><td style="text-align:left;">即時模糊過濾搜尋結果（支援中文拼音首字母與全拼）。</td></tr><tr><td style="text-align:left;"><code>↑</code> / <code>↓</code></td><td style="text-align:left;">向上 / 向下移動當前反白項目。</td></tr><tr><td style="text-align:left;"><code>Page Up</code> / <code>Page Down</code></td><td style="text-align:left;">向上 / 向下快速翻頁。</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code></td><td style="text-align:left;">在底部搜尋輸入框中左右移動游標。</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">切換選取/取消選取當前反白項目（被多選標記的行會帶有 <code>*</code> 標識）。</td></tr><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">將所有標記的路徑（若無標記則輸出當前反白項目路徑）輸出至 <code>stdout</code> 並退出。</td></tr><tr><td style="text-align:left;"><code>Esc</code> 或 <code>Ctrl+C</code></td><td style="text-align:left;">不輸出任何內容，直接安全退出。</td></tr></tbody></table><h2 id="_4-預填關鍵字與管道傳參" tabindex="-1">4. 預填關鍵字與管道傳參 <a class="header-anchor" href="#_4-預填關鍵字與管道傳參" aria-label="Permalink to &quot;4. 預填關鍵字與管道傳參&quot;">​</a></h2><p>你可以直接在啟動參數中指定初始搜尋詞，或透過標準輸入管道傳入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 參數預填</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 管道傳入</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lff</span></span></code></pre></div><p>兩種方式都會自動以 <code>report</code> 作為初始過濾詞開啟互動介面，你可以繼續鍵盤微調或直接按 <code>Enter</code> 確認輸出。</p><h2 id="_5-多選標記與批次輸出" tabindex="-1">5. 多選標記與批次輸出 <a class="header-anchor" href="#_5-多選標記與批次輸出" aria-label="Permalink to &quot;5. 多選標記與批次輸出&quot;">​</a></h2><p>按下 <code>Tab</code> 鍵可以標記當前行。值得注意的是，<strong>標記狀態在更改搜尋關鍵字後依然會被保留</strong>。</p><p>這意味著你可以先搜尋 <code>doc</code> 標記幾個 Word 文件，再清空輸入 <code>pdf</code> 標記幾個 PDF 報表，最後統一按下 <code>Enter</code> 鍵——<code>lff</code> 會將所有跨多次搜尋選取的檔案路徑以換行符分隔逐行輸出至標準輸出。</p><h2 id="_6-shell-腳本與命令聯動實戰" tabindex="-1">6. Shell 腳本與命令聯動實戰 <a class="header-anchor" href="#_6-shell-腳本與命令聯動實戰" aria-label="Permalink to &quot;6. Shell 腳本與命令聯動實戰&quot;">​</a></h2><p><code>lff</code> 的 TUI 介面直接繪製在主控台緩衝區，不會污染標準輸出串流。只有用戶最終確認選取的檔案路徑才會寫入 <code>stdout</code>，因此可以與各類 Shell 語法無縫組合：</p><h3 id="powershell-常用聯動" tabindex="-1">PowerShell 常用聯動 <a class="header-anchor" href="#powershell-常用聯動" aria-label="Permalink to &quot;PowerShell 常用聯動&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 使用 VS Code 開啟檢索到的檔案</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code (lff)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 獲取選取路徑並賦值給變數</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$target </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lff; cd $target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 將檢索結果作為物件傳遞給後續管道</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lff </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Get-Item</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Length</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LastWriteTime</span></span></code></pre></div><h3 id="cmd-batch-批次處理聯動" tabindex="-1">CMD / Batch 批次處理聯動 <a class="header-anchor" href="#cmd-batch-批次處理聯動" aria-label="Permalink to &quot;CMD / Batch 批次處理聯動&quot;">​</a></h3><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:: 使用 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 迴圈逐行處理選取的路徑</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delims=&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i in (</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&#39;lff&#39;) do code &quot;%i&quot;</span></span></code></pre></div><h2 id="_7-使用局限與設計邊界" tabindex="-1">7. 使用局限與設計邊界 <a class="header-anchor" href="#_7-使用局限與設計邊界" aria-label="Permalink to &quot;7. 使用局限與設計邊界&quot;">​</a></h2><ul><li><strong>依賴前台 App</strong>：<code>lff</code> 自身不包含索引邏輯，必須在 Lertaro App 運行期間使用。</li><li><strong>無圖形預覽</strong>：命令列工具專注於極速路徑輸出與管道組合，如需富文本/音訊影片即時預覽，請在 GUI 視窗中使用<a href="./actions-and-preview.html"><strong>動作選單與預覽</strong></a>。</li></ul>`,28)])])}const g=a(l,[["render",n]]);export{k as __pageData,g as default};
